-- 1. Vai ser pai: o guia do primeiro trimestre para o homem
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  'vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem',
  'Vai ser pai: o guia do primeiro trimestre para o homem',
  'O que muda no corpo dela, o que fazer nas consultas e como ser o apoio que sua esposa precisa nas primeiras 13 semanas.',
  'Ela está grávida e você não sabe por onde começar. O que muda, o que fazer nas consultas e como apoiar sua esposa nas primeiras 13 semanas.',
  $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ela te mostrou o teste positivo e, no meio da alegria, veio a pergunta que todo homem faz em silêncio: e agora, o que eu faço? Ninguém te preparou para isso. Os amigos fazem piada, o pai da sua esposa te olha diferente e você sente que precisa ter respostas antes mesmo de entender as perguntas. Calma. As primeiras 13 semanas são justamente o tempo que Deus dá para o homem se organizar por dentro e por fora."}]},{"type":"paragraph","content":[{"type":"text","text":"Este guia é o mapa do primeiro trimestre pelo olhar do pai: o que acontece no corpo dela e no bebê, como você se comporta nas consultas, o que fazer em casa quando o enjoo chega e por onde começar a "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"arrumar o orçamento da casa"},{"type":"text","text":" antes que a lista de gastos cresça. No fim, você sai sabendo o que é esperado, o que merece atenção e quando a situação exige um médico."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O que acontece nas primeiras 13 semanas"}]},{"type":"paragraph","content":[{"type":"text","text":"O primeiro trimestre vai da concepção até o fim da 13ª semana. É o período em que o bebê sai de um aglomerado de células do tamanho de uma semente para um feto com braços, pernas, batimentos cardíacos e todos os órgãos em formação."}]},{"type":"paragraph","content":[{"type":"text","text":"No corpo da sua esposa, os hormônios disparam. O resultado costuma ser um pacote conhecido: enjoo (muitas vezes de manhã, mas não só), sono fora de hora, cansaço que parece desproporcional, seios doloridos, vontade de urinar toda hora e humor que muda sem aviso. Nada disso é frescura e nada disso é culpa dela. É o corpo construindo uma pessoa. Entender isso muda o jeito como você reage quando ela não consegue levantar do sofá às oito da noite."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semanas 4 a 6: o teste dá positivo, a menstruação não vem e começam os primeiros sintomas"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semanas 7 a 9: o enjoo costuma atingir o pico; o coração do bebê já bate e pode aparecer no ultrassom"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semanas 10 a 12: o risco de perda cai bastante e muitos casais escolhem contar para a família"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semana 13: o enjoo tende a diminuir e o cansaço dá uma trégua; começa o segundo trimestre"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Esse calendário é uma média. Cada gestação tem o próprio ritmo, e quem acompanha de perto é a obstetra. O seu papel não é diagnosticar nada: é observar, anotar e estar presente. Os artigos da seção "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/categoria/paternidade-por-fase","class":null,"rel":null,"target":null}}],"text":"Paternidade por fase"},{"type":"text","text":" acompanham cada etapa daqui para a frente."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O que muda para você, o marido"}]},{"type":"paragraph","content":[{"type":"text","text":"Nada muda no seu corpo, e é exatamente por isso que muitos homens demoram a cair na real. Ela sente o bebê desde o primeiro enjoo; você só vai sentir quando ouvir o coração batendo ou quando pegar o recém-nascido no colo pela primeira vez. Não espere o sentimento chegar para começar a agir. Na vocação do pai, a ação vem antes da emoção."}]},{"type":"paragraph","content":[{"type":"text","text":"O medo é normal. Medo de não dar conta financeiramente, medo de repetir os erros do seu próprio pai e acabar "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}],"text":"gritando em vez de dar limite"},{"type":"text","text":", medo de perder a liberdade. Converse com sua esposa sobre eles, chame para um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante","class":null,"rel":null,"target":null}}],"text":"churrasco de fim de tarde"},{"type":"text","text":" um amigo que já é pai e, se for católico praticante, leve isso para a confissão e para a direção espiritual. Homem que esconde o medo vira homem ausente; homem que nomeia o medo vira homem presente."}]},{"type":"paragraph","content":[{"type":"text","text":"Comece também a pensar na sua saúde. Um pai precisa estar vivo e forte por muitas décadas, e os "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":" não esperam o bebê nascer. Marque o seu check-up no mesmo mês em que ela marcar o pré-natal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Como se comportar nas consultas de pré-natal"}]},{"type":"paragraph","content":[{"type":"text","text":"Vá junto. Não é opcional, não é favor: é o seu filho. Avise no trabalho com antecedência e, se precisar, use a lei a seu favor: a legislação trabalhista prevê ao pai o direito de acompanhar consultas e exames durante a gravidez em alguns dias ao longo da gestação. Confirme a regra atual com o RH e, se houver dúvida, com um advogado."}]},{"type":"paragraph","content":[{"type":"text","text":"Durante a consulta, você tem três funções: ouvir, anotar e perguntar o que ela esqueceu. Grávida no primeiro trimestre está cansada e com a cabeça cheia; você é a memória do casal. Leve um caderno ou use o celular, mas registre:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Os exames pedidos e a data de cada um (tipagem sanguínea, sorologias, glicemia, exame de urina, ultrassom)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"O que ela pode e não pode tomar para o enjoo e para a dor de cabeça, segundo a médica"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"As datas da próxima consulta e do ultrassom de 11 a 14 semanas, um dos mais importantes do trimestre"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Os sinais que a obstetra disse para observar entre uma consulta e outra"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"As perguntas que surgiram em casa e ficaram sem resposta"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Não discuta com a médica na frente da sua esposa e não tente substituir a consulta por vídeos da internet. Se algo não fez sentido, pergunte com respeito."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Enjoo, sono e humor: como ajudar sem atrapalhar"}]},{"type":"paragraph","content":[{"type":"text","text":"Aqui o homem prático se destaca. Enjoo melhora com refeições pequenas e frequentes, então deixe biscoito salgado na cabeceira para ela comer antes de levantar. Cheiros fortes pioram tudo: cozinhar com a janela aberta, assumir o lixo e evitar perfume forte são gestos pequenos que ela nota. Se ela não consegue ficar na cozinha, a cozinha vira sua. Vai ser um bom treino para quando o bebê chegar e você precisar "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"segurar a rotina da casa nos primeiros 30 dias"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Sobre o sono: deixe-a dormir. Não é preguiça, é construção de órgãos. Assuma a louça, a roupa e os compromissos do fim de semana sem reclamar e sem cobrar medalha. Sobre o humor: não leve para o pessoal. Se ela chorou porque o pão acabou, o problema não é o pão nem você. Abrace, resolva o que dá para resolver e não tente consertar sentimento com argumento."}]},{"type":"paragraph","content":[{"type":"text","text":"Um erro comum é o marido se afastar fisicamente porque tem medo de machucar o bebê. Carinho não machuca. A intimidade do casal costuma seguir normalmente no primeiro trimestre, salvo orientação médica contrária; o que muda é o cansaço dela, e aí vale a regra de sempre: o desejo dela vem primeiro, sem pressão e sem ressentimento. Sobre isso, vale ler "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"como ser um marido presente depois que o bebê chega"},{"type":"text","text":", porque os hábitos de agora definem o casamento de depois."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semáforo do pai: primeiro trimestre"}]},{"type":"callout","attrs":{"tone":"ok"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal verde: enjoo que vai e volta, cansaço forte, sono fora de hora, seios doloridos, vontade frequente de urinar, pequenas mudanças de humor e um leve sangramento rosado nos primeiros dias depois do atraso menstrual. É o corpo fazendo o trabalho dele. Cuide da alimentação, do descanso e siga o calendário de consultas."}]}]},{"type":"callout","attrs":{"tone":"warn"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de atenção: vômitos que impedem de comer ou beber por mais de um dia, tontura ao levantar, dor de cabeça que não passa, tristeza ou ansiedade que duram dias seguidos, cólica persistente mesmo sem sangramento. Anote quando começou, o que piora e o que melhora, e antecipe o contato com a obstetra em vez de esperar a próxima consulta."}]}]},{"type":"callout","attrs":{"tone":"bad"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de alerta: sangramento vermelho vivo, principalmente com cólica forte; dor intensa em um dos lados do abdômen; febre alta; vômito sem parar com sinais de desidratação; desmaio. Não espere passar e não pesquise na internet: leve sua esposa ao pronto-socorro de obstetrícia ou ligue para a médica dela agora."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O calendário do pai no primeiro trimestre"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Semanas"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"O que está acontecendo"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"O que o pai faz"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"4 a 6"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Teste positivo, primeiros sintomas, primeira consulta"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Marca o pré-natal com ela, começa o caderno de anotações e revisa o orçamento"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"7 a 9"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pico do enjoo, coração do bebê já bate"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Assume a cozinha e o lixo, garante água e lanches, vai junto ao primeiro ultrassom"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"10 a 12"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Risco de perda cai, hora de contar para a família"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Organiza o anúncio com ela, pesquisa plano de saúde e maternidade, faz o próprio check-up"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"13"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Enjoo diminui, começa o segundo trimestre"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Agenda o ultrassom morfológico, revisa a reserva de emergência e marca uma conversa com o padre"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ser pai no primeiro trimestre é fazer o básico muito bem feito, todo dia, sem esperar aplauso."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dinheiro e trabalho: comece agora, não no oitavo mês"}]},{"type":"paragraph","content":[{"type":"text","text":"O primeiro trimestre é o melhor momento para encarar os números, porque ainda não existe pressa. Sente com sua esposa em um sábado de manhã e monte o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"orçamento familiar de quem vai ser pai"},{"type":"text","text":": renda da casa, gastos fixos, o que muda com o bebê e quanto dá para guardar por mês. Se a reserva de emergência não existe, ela nasce agora. Se existe dívida de cartão, ela entra na frente de qualquer compra de enxoval."}]},{"type":"paragraph","content":[{"type":"text","text":"No trabalho, não tome decisões bruscas. Não é hora de pedir demissão para empreender nem de aceitar uma transferência sem conversar em casa. É hora de entender como funciona a licença-paternidade na sua empresa, se existe extensão pelo programa Empresa Cidadã e como você vai organizar os dias de consulta."}]},{"type":"paragraph","content":[{"type":"text","text":"E cuide do corpo. Um plano simples de "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"treino de 20 minutos em casa"},{"type":"text","text":" três vezes por semana custa zero e te dá energia para os meses que vêm. Enquanto isso, aproveite para deixar a casa em ordem: um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"kit básico de ferramentas"},{"type":"text","text":" resolve a prateleira do quarto do bebê sem depender de ninguém."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fé: São José e a vocação que começa hoje"}]},{"type":"paragraph","content":[{"type":"text","text":"São José também recebeu a notícia de uma gravidez que mudou tudo, e a resposta dele não foi discurso: foi levantar e fazer o que precisava ser feito. É esse o modelo. Se você reza, inclua o bebê na oração da noite com sua esposa desde já; é o primeiro hábito de família que vocês constroem. Se faz tempo que não se confessa, o primeiro trimestre é um bom motivo. Um homem que quer ser pai precisa estar em paz com o próprio Pai."}]},{"type":"paragraph","content":[{"type":"text","text":"Procure o padre da sua paróquia para conversar sobre o batismo. Não é cedo: é sinal de que você já está pensando no filho como pessoa, não como projeto. E, se o medo apertar, reze o terço com ela. Casal que reza junto atravessa o primeiro trimestre com outra serenidade, e chega ao dia de "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-segurar-um-recem-nascido-com-seguranca","class":null,"rel":null,"target":null}}],"text":"segurar o recém-nascido no colo"},{"type":"text","text":" sabendo que não está sozinho."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist do pai: primeiro trimestre"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ir a todas as consultas e anotar exames, datas e orientações"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Assumir cozinha, lixo e compras enquanto o enjoo durar"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Montar o orçamento da casa e começar a reserva de emergência"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Marcar o próprio check-up e combinar a licença-paternidade com o RH"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rezar com a esposa pelo bebê todas as noites"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ficar atento aos sinais do semáforo acima"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Você não precisa saber tudo sobre gravidez para ser um bom pai nas primeiras 13 semanas. Precisa aparecer, observar, servir e decidir com calma. O homem que faz isso no primeiro trimestre chega ao parto como marido confiável e começa a paternidade do jeito certo: presente desde antes de o filho nascer."}]},{"type":"paragraph","content":[{"type":"text","text":"Continue lendo: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"Rotina do pai nos primeiros 30 dias do bebê"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-segurar-um-recem-nascido-com-seguranca","class":null,"rel":null,"target":null}}],"text":"Como segurar um recém-nascido com segurança (e sem medo)"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"Orçamento familiar para quem vai ser pai: passo a passo"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"Como ser um marido presente depois que o bebê chega"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"Exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":" e "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"Treino de 20 minutos em casa para pais sem tempo"},{"type":"text","text":"."}]}]}$body$::jsonb,
  'https://images.unsplash.com/photo-1710897538265-93ca0abac2ff?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080',
  'Marido e esposa grávida com as mãos sobre a barriga',
  (select id from public.categories where slug = 'gestacao-e-parto'),
  coalesce((select id from auth.users where lower(email) = 'contato@vocacaodepai.com.br'), 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa'::uuid),
  'artigo',
  $faq$[{"question":"Posso ir às consultas de pré-natal mesmo trabalhando?","answer":"Sim. A legislação trabalhista prevê ao pai dias para acompanhar consultas e exames da esposa durante a gestação. Confirme a regra em vigor com o RH e, em caso de dúvida, com um advogado; avise com antecedência e vá."},{"question":"O enjoo dela é normal ou devo me preocupar?","answer":"Enjoo que vai e volta é esperado no primeiro trimestre. O sinal de atenção é vômito que impede de comer ou beber por mais de um dia; aí o casal antecipa o contato com a obstetra. Sinais de desidratação ou desmaio pedem pronto-socorro."},{"question":"Quando contar para a família que ela está grávida?","answer":"Muitos casais esperam o fim da 12ª semana, quando o risco de perda cai bastante. Não existe regra: decidam juntos, e inclua os pais de vocês antes dos amigos."},{"question":"A intimidade do casal muda no primeiro trimestre?","answer":"O que muda é o cansaço dela, não a segurança do bebê. Salvo orientação médica contrária, a vida íntima segue normalmente, sempre no ritmo e no desejo da esposa, sem pressão."},{"question":"O que eu deveria resolver primeiro: enxoval ou dinheiro?","answer":"Dinheiro. Orçamento da casa e reserva de emergência vêm antes de qualquer compra. Enxoval se resolve no segundo e no terceiro trimestre, com lista e calma."}]$faq$::jsonb,
  $quiz$[{"question":"Qual é a principal tarefa do pai nas consultas de pré-natal?","options":["Discutir o diagnóstico com a médica","Ouvir, anotar e perguntar o que a esposa esqueceu","Esperar na recepção para não atrapalhar","Pesquisar na internet durante a consulta"],"correct":1,"explanation":"No primeiro trimestre a esposa está cansada e com a cabeça cheia; o pai é a memória do casal. Anotar exames, datas e orientações é a função dele."},{"question":"Sangramento vermelho vivo com cólica forte no primeiro trimestre é:","options":["Sinal verde, acontece com todas","Sinal de atenção, anotar e esperar a próxima consulta","Sinal de alerta: pronto-socorro de obstetrícia agora","Motivo para procurar um vídeo explicativo"],"correct":2,"explanation":"Sangramento vermelho vivo com cólica forte é sinal de alerta. Não se espera: leva-se a esposa ao pronto-socorro obstétrico ou liga-se para a médica imediatamente."},{"question":"Quando começar a organizar o orçamento da casa?","options":["No oitavo mês, quando o enxoval chega","Depois do parto, com os gastos reais","No primeiro trimestre, enquanto não há pressa","Só se a esposa parar de trabalhar"],"correct":2,"explanation":"O primeiro trimestre é o melhor momento: dá tempo de construir reserva, quitar cartão e entender a licença-paternidade sem correria."},{"question":"Como ajudar com o enjoo sem atrapalhar?","options":["Insistir para ela comer refeições grandes","Refeições pequenas e frequentes, evitar cheiros fortes e assumir a cozinha","Dizer que é frescura e passa","Comprar remédio por conta própria"],"correct":1,"explanation":"Refeições pequenas, biscoito salgado na cabeceira, janela aberta ao cozinhar e o pai assumindo a cozinha ajudam de verdade. Remédio só com orientação da obstetra."}]$quiz$::jsonb,
  'published',
  now() - interval '9 days',
  10,
  'Vai ser pai: guia do primeiro trimestre para o homem',
  'O que muda no corpo dela, como agir nas consultas de pré-natal, como ajudar com enjoo e sono e quando procurar a obstetra nas primeiras 13 semanas.'
)
on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, excerpt = excluded.excerpt, body = excluded.body,
  cover_image_url = excluded.cover_image_url, cover_image_alt = excluded.cover_image_alt, category_id = excluded.category_id,
  author_id = excluded.author_id, kind = excluded.kind, faq = excluded.faq, quiz = excluded.quiz,
  reading_time = excluded.reading_time, seo_title = excluded.seo_title, seo_description = excluded.seo_description,
  status = 'published', publish_at = coalesce(public.posts.publish_at, excluded.publish_at), updated_at = now();

-- 2. Como segurar um recém-nascido com segurança (e sem medo)
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  'como-segurar-um-recem-nascido-com-seguranca',
  'Como segurar um recém-nascido com segurança (e sem medo)',
  'As quatro pegadas que todo pai precisa dominar, os erros que oferecem risco de verdade e o que fazer quando o bebê chora no seu colo.',
  'As 4 pegadas que todo pai precisa dominar, os erros mais comuns e o que fazer quando o bebê chora no seu colo. Passo a passo com checklist.',
  $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O bebê nasceu, a enfermeira coloca ele nos seus braços e você trava. Parece que vai quebrar. A cabeça balança, o pescoço não sustenta nada, e todo mundo em volta está olhando. Quase todo pai passa por esse segundo de pânico, e quase nenhum fala disso. Segurar um recém-nascido é uma habilidade, não um instinto; e habilidade se aprende."}]},{"type":"paragraph","content":[{"type":"text","text":"Aqui você vai ver as quatro pegadas que resolvem quase todas as situações, os erros que realmente oferecem risco, o que fazer quando ele chora no seu colo e como transformar isso em rotina dentro dos "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"primeiros 30 dias do bebê em casa"},{"type":"text","text":". Leia uma vez, pratique no mesmo dia e o medo vai embora mais rápido do que você imagina."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Por que o medo é normal (e por que ele passa)"}]},{"type":"paragraph","content":[{"type":"text","text":"Um recém-nascido pesa em média entre 2,5 e 4 quilos e tem a cabeça proporcionalmente grande e pesada para um pescoço que ainda não tem força. Seu corpo de homem adulto entende instintivamente que aquilo é frágil, e a resposta é tensão: braços duros, ombros levantados, respiração presa. O bebê sente essa tensão e chora, o que aumenta a sua tensão. É um ciclo, e ele se quebra de um jeito só: segurando o bebê mais vezes, não menos."}]},{"type":"paragraph","content":[{"type":"text","text":"Pai que entrega o filho para a mãe toda vez que ele chora não aprende nunca. Pai que fica com o bebê dez minutos por dia, mesmo chorando, em uma semana está carregando o filho pela casa com uma mão enquanto esquenta a mamadeira com a outra. Não é talento, é repetição. E é uma das primeiras formas de ser "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"um marido presente depois que o bebê chega"},{"type":"text","text":": dar à sua esposa a certeza de que ela pode tomar banho em paz."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Antes de pegar: mãos, postura e ambiente"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lave as mãos com água e sabão por pelo menos 20 segundos; recém-nascido não tem a imunidade de um adulto"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tire relógio, pulseira e anel com pedra, que arranham a pele fina do bebê"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sente-se nas primeiras vezes; segurar sentado tira o medo de deixar cair"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Respire fundo e solte os ombros antes de pegar; o bebê lê o seu corpo"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nunca pegue o bebê depois de beber álcool, com sono extremo ou enquanto mexe no celular"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Parece exagero, mas a maior parte dos acidentes com bebês no colo acontece por distração do adulto, não por falta de técnica. A técnica vem a seguir; a atenção é inegociável. Se você ainda está na gestação, leia o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"guia do primeiro trimestre para o homem"},{"type":"text","text":" e comece a praticar com a almofada: parece bobagem, mas treina o braço."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"As 4 pegadas que todo pai precisa dominar"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Pegada do berço (clássica). "},{"type":"text","text":"Deslize uma mão por baixo da cabeça e do pescoço e a outra por baixo do bumbum. Traga o bebê para o seu peito e deixe a cabeça apoiada na dobra do seu cotovelo, com o corpo ao longo do antebraço. É a pegada para dar mamadeira, olhar nos olhos e acalmar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Pegada no ombro. "},{"type":"text","text":"Apoie o peito do bebê contra o seu peito, com a cabeça encostada no seu ombro. Uma mão sustenta o bumbum, a outra fica espalmada nas costas e na nuca. É a melhor pegada para arrotar e para ninar andando pela casa."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Pegada de bruços no antebraço (a “pegada do jogador”). "},{"type":"text","text":"Deite o bebê de barriga para baixo ao longo do seu antebraço, com a bochecha apoiada perto da dobra do cotovelo e as pernas de cada lado do seu braço. A outra mão fica sobre as costas. Alivia cólica e costuma parar choro que nada mais para."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Pegada sentada de frente. "},{"type":"text","text":"Sente o bebê no seu colo, de costas para você, com uma mão espalmada no peito dele segurando o queixo entre o polegar e o indicador e a outra apoiando o bumbum. Serve para arrotar e, mais tarde, para ele olhar o mundo. Nos primeiros dias, use só por poucos minutos e sempre com a cabeça sustentada."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Em todas elas a regra é uma: a cabeça nunca fica solta. Enquanto o pescoço não sustentar sozinho, por volta dos três ou quatro meses, uma mão ou um braço seu está sempre atrás da cabeça e da nuca."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Os erros mais comuns dos pais de primeira viagem"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Levantar o bebê pelas axilas sem apoiar a cabeça, que cai para trás"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sacudir o bebê para “acordar” ou para fazer parar de chorar; isso pode causar lesão cerebral grave"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Segurar com um braço só enquanto desce escada, abre porta ou carrega outra coisa"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deixar o bebê dormir no seu peito deitado no sofá; o risco de sufocamento e queda é real"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passar o bebê de um adulto para outro “no ar”, sem apoiar na dobra do braço de quem recebe"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deitar o bebê de bruços para dormir; de bruços só no colo e acordado, para dormir é de barriga para cima"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Nenhum desses erros é falta de amor; é falta de informação. Agora você tem a informação. Se alguém da família insistir em sacudir, balançar com força ou colocar o bebê para dormir de bruços “porque sempre foi assim”, o pai diz não. É você quem dá os limites da casa, e "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}],"text":"dar limite com calma e sem gritar"},{"type":"text","text":" começa com os adultos, não com as crianças."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Quando o bebê chora no seu colo"}]},{"type":"paragraph","content":[{"type":"text","text":"Choro é comunicação, não julgamento da sua capacidade. Antes de devolver para a mãe, faça a checagem básica em um minuto: fralda, fome (a última mamada foi há quanto tempo?), frio ou calor, roupa apertada, sono. Se nada disso é, vá para o que funciona com a maioria dos recém-nascidos: pegada no ombro ou de bruços no antebraço, balanço leve e ritmado, sua voz grave falando baixo perto do ouvido dele. Voz de homem acalma; o bebê ouviu você de dentro da barriga por meses."}]},{"type":"paragraph","content":[{"type":"text","text":"Se depois de dez ou quinze minutos ele continua chorando e você sente a raiva subindo, coloque o bebê no berço de barriga para cima, saia do quarto, respire, lave o rosto e volte. Um bebê chorando sozinho por dois minutos em um lugar seguro está bem; um bebê sacudido por um pai que perdeu a cabeça não está. Essa é a regra mais importante deste artigo. Cuidar do próprio sono e da própria energia, com "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"treino curto em casa"},{"type":"text","text":" e horário de dormir, também faz parte de segurar o bebê com segurança."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semáforo do pai: o colo do recém-nascido"}]},{"type":"callout","attrs":{"tone":"ok"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal verde: o bebê chora, se acalma no colo em alguns minutos, mama, dorme, faz xixi e cocô todo dia; a cabeça balança um pouco quando você muda de posição, mas está sempre apoiada; ele soluça, espirra e faz barulhinhos ao respirar durante o sono. Tudo normal para um recém-nascido saudável."}]}]},{"type":"callout","attrs":{"tone":"warn"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de atenção: choro que dura mais de duas horas seguidas sem nada que acalme, recusa de duas mamadas seguidas, menos de seis fraldas molhadas por dia depois da primeira semana, bebê muito molinho ou muito rígido no colo, vômito em jato depois de várias mamadas. Anote e ligue para a pediatra ainda hoje."}]}]},{"type":"callout","attrs":{"tone":"bad"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de alerta: queda do colo ou de qualquer altura, batida na cabeça, bebê sacudido por alguém, dificuldade para respirar, lábios ou pele arroxeados, febre em bebê com menos de três meses, moleza extrema com dificuldade para acordar. Não observe em casa: vá ao pronto-socorro infantil ou chame o SAMU (192) agora e avise a pediatra."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Qual pegada usar em cada situação"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Pegada"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Quando usar"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuidado principal"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Berço (clássica)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Mamadeira, ninar sentado, olhar nos olhos"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Cabeça sempre na dobra do cotovelo, nunca pendurada"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No ombro"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrotar, andar pela casa, acalmar"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Mão espalmada na nuca; cuidado com portas e batentes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"De bruços no antebraço"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Cólica, choro difícil, gases"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Bochecha apoiada, nariz livre, só com o bebê acordado"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sentada de frente"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrotar, trocar de posição, bebê maior"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Queixo entre polegar e indicador, poucos minutos no começo"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passar para outro adulto"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Visitas, avós, mãe"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Quem recebe já com o braço na posição; nunca “no ar”"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trocar fralda, dar banho e arrotar: a pegada na prática"}]},{"type":"paragraph","content":[{"type":"text","text":"Na troca de fralda, o erro é levantar o bebê pelos pés com força; levante o bumbum segurando os dois tornozelos com uma mão só, com o dedo entre eles, e deslize a fralda com a outra. No banho, a pegada é o antebraço por trás das costas com a mão segurando a axila do lado oposto; o bebê fica meio deitado na água morna e a sua outra mão fica livre. Teste a temperatura com o cotovelo, nunca com a mão."}]},{"type":"paragraph","content":[{"type":"text","text":"Para arrotar, pegada no ombro ou sentada de frente, tapinhas leves e ritmados no meio das costas por alguns minutos. Se não arrotar, não insista eternamente: nem toda mamada gera arroto. Deite-o de lado por alguns minutos no seu colo e tente de novo. Tudo isso fica mais fácil quando a casa está organizada e você sabe onde estão as coisas; o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"kit básico de ferramentas"},{"type":"text","text":" pode esperar, mas o trocador com tudo à mão não. E, se o dinheiro aperta com fralda e pomada, o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"orçamento familiar de quem vai ser pai"},{"type":"text","text":" ajuda a colocar cada gasto no lugar."}]},{"type":"paragraph","content":[{"type":"text","text":"Quando a avó ou a sogra disser que você está segurando errado, ouça com respeito, agradeça e continue segurando do jeito que a pediatra orientou. Pai seguro não precisa vencer discussão; precisa segurar bem o filho. E, se o cansaço bater, lembre que o seu check-up também importa: os "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":" não tiram folga porque você virou pai. Comemore o primeiro mês com um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante","class":null,"rel":null,"target":null}}],"text":"churrasco simples no quintal"},{"type":"text","text":", com o bebê no colo e os amigos por perto; e siga acompanhando as próximas fases na seção "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/categoria/paternidade-por-fase","class":null,"rel":null,"target":null}}],"text":"Paternidade por fase"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist do pai: segurar o bebê"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Lavar as mãos e tirar relógio e anéis antes de pegar o bebê"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Apoiar a cabeça e a nuca em toda pegada até o pescoço firmar"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Treinar as quatro pegadas sentado nos primeiros dias"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Nunca sacudir o bebê; se a raiva subir, colocar no berço e sair do quarto"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Dormir de barriga para cima, no berço, sem travesseiro nem cobertor solto"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ficar atento aos sinais do semáforo acima"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Daqui a um mês você vai pegar seu filho no colo com uma mão, sem pensar, enquanto conversa com alguém. O caminho até lá é curto e passa por uma decisão simples: pegar o bebê hoje, com medo mesmo, e de novo amanhã. Homem que segura o filho com firmeza e carinho nos primeiros dias segura a família inteira pelo resto da vida."}]},{"type":"paragraph","content":[{"type":"text","text":"Continue lendo: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"Rotina do pai nos primeiros 30 dias do bebê"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"Como ser um marido presente depois que o bebê chega"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"Vai ser pai: o guia do primeiro trimestre para o homem"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}],"text":"Como dar limites sem gritar: autoridade com calma"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"Treino de 20 minutos em casa para pais sem tempo"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"Exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":" e "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"Kit básico de ferramentas para a casa: o que todo pai precisa ter"},{"type":"text","text":"."}]}]}$body$::jsonb,
  'https://images.unsplash.com/photo-1650872466823-433d9e461b9d?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080',
  'Pai segurando o filho recém-nascido no colo',
  (select id from public.categories where slug = 'recem-nascido'),
  coalesce((select id from auth.users where lower(email) = 'contato@vocacaodepai.com.br'), 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa'::uuid),
  'artigo',
  $faq$[{"question":"Até quando preciso apoiar a cabeça do bebê?","answer":"Até o pescoço sustentar sozinho, o que costuma acontecer por volta dos três ou quatro meses. Antes disso, em qualquer pegada, uma mão ou o seu braço fica sempre atrás da cabeça e da nuca."},{"question":"Posso segurar o bebê de bruços?","answer":"Sim, no seu antebraço e com ele acordado: é a pegada que mais alivia cólica. Para dormir, nunca de bruços. Bebê dorme de barriga para cima, no berço, sem travesseiro nem cobertor solto."},{"question":"E se ele chorar toda vez que eu pegar?","answer":"O bebê sente a sua tensão. Sente-se, solte os ombros, fale baixo com a voz grave e balance de leve. Continue pegando todo dia; em uma semana ele se acostuma com o seu colo."},{"question":"O que fazer se eu sentir raiva do choro?","answer":"Coloque o bebê no berço de barriga para cima, saia do quarto, respire e volte depois de alguns minutos. Um bebê chorando em lugar seguro está bem; um bebê sacudido não está. Se a raiva for frequente, converse com a pediatra ou com um psicólogo."},{"question":"Bebê caiu do colo: o que faço?","answer":"Mesmo sem sinal aparente, é sinal de alerta: vá ao pronto-socorro infantil ou chame o SAMU (192) e avise a pediatra. Não dê remédio nem observe em casa por conta própria."}]$faq$::jsonb,
  $quiz$[{"question":"Qual é a regra que vale para todas as pegadas do recém-nascido?","options":["Segurar sempre com as duas mãos","A cabeça nunca fica solta","Nunca segurar em pé","Trocar de pegada a cada minuto"],"correct":1,"explanation":"Enquanto o pescoço não sustentar sozinho, a cabeça e a nuca estão sempre apoiadas por uma mão ou pelo braço, em qualquer pegada."},{"question":"O bebê chora há quinze minutos no seu colo e você sente a raiva subindo. O que fazer?","options":["Balançar com mais força para ele parar","Entregar para a mãe e sair de casa","Colocar no berço de barriga para cima, sair do quarto e respirar","Deixar no sofá e ir ver televisão"],"correct":2,"explanation":"Bebê em lugar seguro pode chorar por alguns minutos. Sacudir ou balançar com força pode causar lesão cerebral grave; sofá não é lugar seguro."},{"question":"Qual pegada costuma aliviar cólica?","options":["Berço clássica","No ombro","De bruços no antebraço","Sentada de frente"],"correct":2,"explanation":"Na pegada de bruços no antebraço, a pressão leve na barriga e o balanço aliviam gases e cólica. Só com o bebê acordado e com o nariz livre."},{"question":"Febre em bebê com menos de três meses é:","options":["Normal, bebê esquenta fácil","Sinal de atenção, dar banho morno","Sinal de alerta: pronto-socorro agora","Motivo para esperar a próxima consulta"],"correct":2,"explanation":"Febre antes dos três meses é sempre sinal de alerta e pede avaliação médica imediata, no pronto-socorro infantil ou com a pediatra."}]$quiz$::jsonb,
  'published',
  now() - interval '8 days',
  10,
  'Como segurar um recém-nascido com segurança: 4 pegadas',
  'As quatro pegadas para segurar o recém-nascido, os erros que oferecem risco, o que fazer quando ele chora no seu colo e quando procurar a pediatra.'
)
on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, excerpt = excluded.excerpt, body = excluded.body,
