  author_id = excluded.author_id, kind = excluded.kind, faq = excluded.faq, quiz = excluded.quiz,
  reading_time = excluded.reading_time, seo_title = excluded.seo_title, seo_description = excluded.seo_description,
  status = 'published', publish_at = coalesce(public.posts.publish_at, excluded.publish_at), updated_at = now();

-- 3. Rotina do pai nos primeiros 30 dias do bebê
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  'rotina-do-pai-nos-primeiros-30-dias-do-bebe',
  'Rotina do pai nos primeiros 30 dias do bebê',
  'Divisão de tarefas, noites, visitas e o seu papel enquanto a mãe se recupera: um plano semana a semana para o pai não virar espectador.',
  'Divisão de tarefas, noites, visitas e o seu papel enquanto a mãe se recupera. Um plano semana a semana para o pai não virar espectador.',
  $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vocês chegaram em casa com o bebê, a porta fechou e o silêncio do hospital deu lugar a uma pergunta que ninguém responde direito: o que o pai faz agora? A mãe está dolorida, amamentando a cada duas horas e com os hormônios em queda livre. O bebê chora, dorme e mama sem relógio. E você está ali, no meio, correndo o risco de virar espectador na própria casa."}]},{"type":"paragraph","content":[{"type":"text","text":"Este artigo é um plano de 30 dias, semana a semana, para o pai assumir a casa, a noite, as visitas e a volta ao trabalho sem sumir. Ele parte de uma ideia simples: nos primeiros 30 dias, a mãe cuida do bebê e o pai cuida da mãe, da casa e de tudo o que permite que ela cuide do bebê. Se você ainda não sabe nem "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-segurar-um-recem-nascido-com-seguranca","class":null,"rel":null,"target":null}}],"text":"segurar o recém-nascido com segurança"},{"type":"text","text":", comece por lá e volte aqui."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O que a mãe está vivendo (e por que você é peça-chave)"}]},{"type":"paragraph","content":[{"type":"text","text":"O pós-parto, ou puerpério, dura cerca de seis semanas. O corpo dela está fechando um útero que cresceu dez vezes, cicatrizando parto normal ou cesárea, produzindo leite e lidando com uma queda brusca de hormônios que mexe diretamente com o humor. Soma-se a isso dormir em blocos de uma ou duas horas. Não existe cansaço de trabalho que se compare."}]},{"type":"paragraph","content":[{"type":"text","text":"Por isso a sua presença não é ajuda: é parte do cuidado. Mulher que tem o marido ao lado nos primeiros 30 dias amamenta por mais tempo, se recupera melhor e tem menos risco de depressão pós-parto. Isso não é opinião de blog, é o que as equipes de saúde observam todo dia. O pai que entende isso para de perguntar “precisa de alguma coisa?” e começa a fazer. Se você leu o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"guia do primeiro trimestre"},{"type":"text","text":", já sabe: a ação vem antes da emoção."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semana 1: chegada em casa e licença-paternidade"}]},{"type":"paragraph","content":[{"type":"text","text":"A primeira semana é de instalação. Use a licença-paternidade inteira (cinco dias pela CLT, vinte na Empresa Cidadã; confira no RH e, se precisar, com um advogado) e não aceite “deixa para depois”. Nesses dias, a casa é sua: compras, cozinha, louça, roupa, lixo, telefone. A mãe só tem duas tarefas, amamentar e descansar. Tudo o que não for isso é com você."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monte a estação de amamentação: água, lanche, carregador, almofada e um lugar para o pai sentar junto"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Organize o trocador e o banho com tudo à mão para não deixar o bebê sozinho em cima de nada"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assuma o registro de nascimento, a inclusão no plano de saúde e a marcação da primeira consulta do pediatra"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Controle as visitas: nos primeiros sete dias, só quem ajuda, por pouco tempo e com as mãos lavadas"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cozinhe simples e em quantidade; congele porções para a semana seguinte"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ainda na primeira semana, sente com ela para revisar o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"orçamento da casa com o bebê"},{"type":"text","text":": fraldas, consultas e a mudança na renda, se ela estiver de licença. Dez minutos de conversa agora evitam briga por dinheiro no segundo mês."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semana 2: a noite é sua também"}]},{"type":"paragraph","content":[{"type":"text","text":"É aqui que muitos pais se perdem com a frase “eu trabalho amanhã”. Ela também trabalha amanhã, e sem direito a folga. A noite precisa ser dividida com inteligência, não ignorada. O modelo que mais funciona com amamentação exclusiva é este: a mãe mama, o pai arrota, troca a fralda e faz o bebê dormir de novo. Ela volta a dormir dez ou quinze minutos antes de você, e isso soma horas ao longo da semana."}]},{"type":"paragraph","content":[{"type":"text","text":"Se houver mamadeira (leite extraído ou fórmula, por orientação da pediatra), combine um turno: você fica com a mamada da meia-noite ou das duas da manhã e ela dorme um bloco de quatro horas seguidas. Quatro horas de sono contínuo mudam o humor de qualquer pessoa. Para aguentar o pique, mantenha o corpo em ordem: um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"treino de 20 minutos em casa"},{"type":"text","text":" antes de o bebê acordar faz mais pelo seu sono do que uma hora extra na cama."}]},{"type":"paragraph","content":[{"type":"text","text":"E, pelo amor de Deus, não durma com o bebê no sofá nem na poltrona de madrugada. Se o sono bater durante o colo, coloque o bebê no berço, de barriga para cima, e só então deite."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semana 3: visitas, limites e a casa funcionando"}]},{"type":"paragraph","content":[{"type":"text","text":"Na terceira semana, a família toda quer conhecer o bebê, e é o pai quem organiza isso. Visita boa chega com comida, fica no máximo uma hora, lava as mãos, não beija o rosto do bebê e vai embora sem ser mandada. Visita que vem para ser servida não vem. Você vai desagradar alguém, provavelmente a sua própria mãe ou a sogra. Faça isso com educação e firmeza; é a primeira vez que você protege sua família de algo externo, e não vai ser a última."}]},{"type":"paragraph","content":[{"type":"text","text":"É também a semana de ensaiar o que vai dizer quando alguém opinar sobre amamentação, sono ou colo. A resposta padrão é curta: “a pediatra orientou assim”. Esse mesmo tom firme e calmo é o que você vai usar daqui a alguns anos para "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}],"text":"dar limites sem gritar"},{"type":"text","text":"; comece a praticar com os adultos."}]},{"type":"paragraph","content":[{"type":"text","text":"Para a casa funcionar, defina um padrão mínimo e aceite que ele é menor do que antes. Cozinha limpa à noite, roupa lavada duas vezes por semana, compras uma vez por semana. O resto espera. Um churrasco rápido no quintal no domingo, com uma "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante","class":null,"rel":null,"target":null}}],"text":"carne bem escolhida"},{"type":"text","text":" e dois amigos que já são pais, faz bem para ela, para você e para o clima da casa."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semana 4: a volta ao trabalho sem sumir"}]},{"type":"paragraph","content":[{"type":"text","text":"A licença acabou, e o perigo agora é o oposto do primeiro: o pai volta ao trabalho e desliga de casa. A solução é uma rotina fixa e pequena, que não dependa de humor. Acorde quinze minutos antes, deixe a estação de amamentação pronta e o café dela na mesa. Ligue uma vez no meio do dia, não para perguntar se está tudo bem, mas para dizer que está chegando às tal horas. Chegue e, antes de qualquer coisa, pegue o bebê por meia hora para ela tomar banho e comer sentada."}]},{"type":"paragraph","content":[{"type":"text","text":"À noite, mantenha o turno combinado. No fim de semana, o sábado de manhã é dela: você sai com o bebê para passear ou simplesmente fica no quarto com ele enquanto ela dorme três horas seguidas. Esse hábito, mantido por meses, é o que separa um pai que “ajuda” de um pai que lidera a casa. O passo seguinte é cuidar do casamento, e para isso vale ler "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"como ser um marido presente depois que o bebê chega"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semáforo do pai: os primeiros 30 dias"}]},{"type":"callout","attrs":{"tone":"ok"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal verde: a mãe chora à toa nos primeiros dias, sente dor ao amamentar no começo, tem sangramento que diminui semana a semana e cansaço forte; o bebê mama a cada duas ou três horas, dorme muito, chora ao fim da tarde e molha pelo menos seis fraldas por dia. É o esperado para o primeiro mês."}]}]},{"type":"callout","attrs":{"tone":"warn"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de atenção: tristeza ou irritação que não melhoram depois de duas semanas, mãe que não consegue dormir mesmo quando o bebê dorme, seio vermelho e dolorido com febre baixa, sangramento que volta a aumentar, bebê que mama pouco ou perde peso depois da primeira consulta. Anote os sinais e antecipe o contato com a obstetra ou a pediatra."}]}]},{"type":"callout","attrs":{"tone":"bad"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de alerta: sangramento intenso que encharca um absorvente em menos de uma hora, febre alta, dor forte na barriga ou na perna, falta de ar, mãe dizendo que não quer mais viver ou que pode fazer mal a si ou ao bebê; bebê com febre antes dos três meses, lábios roxos, moleza extrema ou mais de seis horas sem mamar. Não espere: leve ao pronto-socorro, ligue para a obstetra ou para a pediatra e chame o SAMU (192) se for grave."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Divisão de tarefas nos primeiros 30 dias"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Tarefa"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Quem faz"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Quando"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Amamentar e descansar"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Mãe"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Livre demanda, dia e noite"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrotar, trocar e fazer dormir depois da mamada"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pai"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Todas as mamadas em que estiver em casa, inclusive de madrugada"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Compras, cozinha, louça, roupa e lixo"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pai"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Diário, com padrão mínimo combinado"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Visitas, telefonemas e recados da família"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pai"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Filtradas, curtas, só a partir da segunda semana"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Documentos, plano de saúde e consultas"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pai"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Primeira semana e a cada consulta"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Banho do bebê"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pai (com a mãe por perto no começo)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fim de tarde, todo dia"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A tabela não é um contrato definitivo; é o ponto de partida. Depois do primeiro mês, vocês reequilibram, e a seção "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/categoria/paternidade-por-fase","class":null,"rel":null,"target":null}}],"text":"Paternidade por fase"},{"type":"text","text":" mostra o que vem a seguir. Mas no primeiro mês o desequilíbrio é proposital: ela produz o leite, você produz o resto. Montar berço, prateleira e trocador antes do parto, com o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"kit básico de ferramentas"},{"type":"text","text":" em mãos, poupa noites de improviso."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"E a fé da família, nesse meio tempo?"}]},{"type":"paragraph","content":[{"type":"text","text":"Primeiro mês não é tempo de grandes devoções, é tempo de pequenas fidelidades. Uma Ave-Maria com ela antes de dormir, a bênção na testa do bebê antes de sair para o trabalho, a missa do domingo mesmo que você vá sozinho enquanto ela descansa. Marque a conversa com o padre sobre o batismo ainda neste mês. E lembre que o seu corpo também precisa de manutenção: não deixe para depois os "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist do pai: primeiros 30 dias"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Usar a licença-paternidade inteira e assumir a casa na primeira semana"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Dividir a noite com um turno fixo e nunca dormir com o bebê no sofá"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Filtrar visitas e proteger o descanso da mãe com firmeza"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Montar a rotina de volta ao trabalho com horário de chegada e meia hora de bebê no colo"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rezar com a esposa e marcar a conversa sobre o batismo"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ficar atento aos sinais do semáforo acima"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Trinta dias passam rápido e definem muita coisa. O pai que assume a casa, a noite e as visitas no primeiro mês não está fazendo um favor para a esposa; está exercendo a vocação para a qual foi chamado. Você vai errar, vai cansar e vai, em algum dia, querer fugir para o trabalho. Fique. É assim que se constrói uma família que dura."}]},{"type":"paragraph","content":[{"type":"text","text":"Continue lendo: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-segurar-um-recem-nascido-com-seguranca","class":null,"rel":null,"target":null}}],"text":"Como segurar um recém-nascido com segurança (e sem medo)"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"Como ser um marido presente depois que o bebê chega"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"Vai ser pai: o guia do primeiro trimestre para o homem"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}],"text":"Como dar limites sem gritar: autoridade com calma"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"Orçamento familiar para quem vai ser pai: passo a passo"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"Treino de 20 minutos em casa para pais sem tempo"},{"type":"text","text":" e "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"Exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":"."}]}]}$body$::jsonb,
  'https://images.unsplash.com/photo-1773243086594-43577199874f?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080',
  'Pai segurando com cuidado o bebê recém-nascido',
  (select id from public.categories where slug = 'recem-nascido'),
  coalesce((select id from auth.users where lower(email) = 'contato@vocacaodepai.com.br'), 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa'::uuid),
  'artigo',
  $faq$[{"question":"Quantos dias de licença-paternidade eu tenho?","answer":"Pela CLT são cinco dias corridos; empresas no programa Empresa Cidadã estendem para vinte. Servidores e categorias com acordo coletivo podem ter regras próprias. Confirme no RH e, em caso de dúvida, com um advogado."},{"question":"Se ela amamenta, o que eu faço à noite?","answer":"A mãe mama; o pai arrota, troca a fralda e faz o bebê dormir de novo. Ela volta a dormir antes de você, e isso soma horas na semana. Com leite extraído ou fórmula, por orientação da pediatra, o pai assume um turno inteiro."},{"question":"Posso receber visitas na primeira semana?","answer":"Só quem ajuda, por pouco tempo e com as mãos lavadas. Visita que vem para ser servida fica para depois do primeiro mês. É o pai quem organiza e diz não quando precisa."},{"question":"Como saber se a tristeza dela é normal?","answer":"Choro fácil nos primeiros dias é esperado. Tristeza, irritação ou insônia que não melhoram depois de duas semanas pedem contato com a obstetra. Qualquer fala sobre não querer viver ou fazer mal a si ou ao bebê é emergência."},{"question":"Preciso mesmo dar o banho do bebê?","answer":"Precisa. É a tarefa mais fácil de o pai assumir todo dia, cria vínculo e dá à mãe meia hora de descanso. Nos primeiros banhos, a mãe fica por perto e você vai ganhando confiança."}]$faq$::jsonb,
  $quiz$[{"question":"Nos primeiros 30 dias, qual é a divisão de papéis proposta?","options":["A mãe cuida de tudo e o pai trabalha","O pai cuida do bebê e a mãe descansa","A mãe cuida do bebê e o pai cuida da mãe, da casa e do resto","Cada um cuida do bebê em dias alternados"],"correct":2,"explanation":"No primeiro mês a mãe amamenta e se recupera; o pai assume a casa, as noites, as visitas e tudo o que permite que ela cuide do bebê."},{"question":"O bebê dormiu no seu colo de madrugada e o sono bateu. O que fazer?","options":["Deitar no sofá com ele no peito","Colocar no berço de barriga para cima e só então deitar","Deixar na poltrona e ir para a cama","Acordar o bebê para mamar"],"correct":1,"explanation":"Dormir com o bebê no sofá ou na poltrona tem risco real de sufocamento e queda. Berço, de barriga para cima, sempre."},{"question":"Sangramento que encharca um absorvente em menos de uma hora, no pós-parto, é:","options":["Normal nas primeiras semanas","Sinal de atenção, observar até o dia seguinte","Sinal de alerta: pronto-socorro ou obstetra agora","Motivo para aumentar a ingestão de água"],"correct":2,"explanation":"Sangramento intenso é sinal de alerta no pós-parto. Não se espera: pronto-socorro, obstetra ou SAMU."},{"question":"Qual é o maior risco na quarta semana, quando o pai volta ao trabalho?","options":["Esquecer o nome do pediatra","Desligar de casa e virar espectador","Dormir demais","Ganhar peso"],"correct":1,"explanation":"Depois da licença, o perigo é o pai mergulhar no trabalho e sumir. A solução é uma rotina fixa e pequena: café pronto, ligação no meio do dia, meia hora de bebê no colo ao chegar."}]$quiz$::jsonb,
  'published',
  now() - interval '7 days',
  9,
  'Rotina do pai nos primeiros 30 dias do bebê: plano',
  'Plano semana a semana para o pai nos primeiros 30 dias: licença, divisão da noite, visitas, volta ao trabalho e os sinais que pedem médico.'
)
