-- 4. Como dar limites sem gritar: autoridade com calma
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  'como-dar-limites-sem-gritar-autoridade-com-calma',
  'Como dar limites sem gritar: autoridade com calma',
  'Limite firme não é grito. O método de três passos para corrigir, as frases que funcionam por idade e o que fazer quando você perde a paciência.',
  'Limite firme não é grito. Veja o método de 3 passos para corrigir, as frases que funcionam por idade e o que fazer quando você perde a paciência.',
  $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Você pediu três vezes para ele guardar o brinquedo. Na quarta, gritou. Ele chorou, guardou e você ficou com aquele gosto amargo de quem venceu a batalha e perdeu alguma coisa maior. Se essa cena se repete na sua casa, você não é um pai ruim; é um pai sem método. E método se aprende."}]},{"type":"paragraph","content":[{"type":"text","text":"Neste artigo você vai entender por que o grito não funciona, a diferença entre autoridade e autoritarismo, o método de três passos para corrigir com calma, as frases que funcionam em cada idade e o que fazer quando você perde a paciência, porque vai perder. Tudo isso se apoia num princípio que começa cedo, lá nos "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"primeiros 30 dias do bebê"},{"type":"text","text":": quem dá o tom da casa é o pai, e o tom se dá com a voz baixa."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Por que o grito não funciona (e o que ele ensina)"}]},{"type":"paragraph","content":[{"type":"text","text":"O grito funciona uma vez. Na segunda, a criança já aprendeu que o pai só está falando sério quando levanta a voz, e passa a ignorar tudo o que vem antes. Você vai precisar gritar mais alto, mais cedo, mais vezes. Em alguns meses, a criança obedece ao volume, não à autoridade; e, quando crescer o suficiente para não ter medo do volume, não vai sobrar nada."}]},{"type":"paragraph","content":[{"type":"text","text":"Pior do que isso é o que o grito ensina. Ele ensina que quem está nervoso pode descontar em quem é menor. Ensina que limite é ataque. Ensina que o pai perde o controle. A criança não aprende o que você diz; aprende o que você faz. Se você quer um filho que respira antes de reagir, ele precisa ver você respirando antes de reagir."}]},{"type":"paragraph","content":[{"type":"text","text":"Há ainda o efeito no casamento. Esposa que vê o marido gritando com o filho perde a confiança de que ele é um porto seguro, e isso corrói a intimidade do casal. Ser "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"um marido presente"},{"type":"text","text":" passa também por como você fala com os filhos quando está cansado."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Autoridade é diferente de autoritarismo"}]},{"type":"paragraph","content":[{"type":"text","text":"Autoridade é quando o filho obedece porque confia em você e sabe que você sustenta o que diz. Autoritarismo é quando ele obedece porque tem medo. A primeira forma um homem; a segunda forma um covarde ou um rebelde. Pai de autoridade fala uma vez, em tom normal, olhando nos olhos, e cumpre o que prometeu. Pai autoritário fala dez vezes, cada vez mais alto, e ameaça o que não vai cumprir."}]},{"type":"paragraph","content":[{"type":"text","text":"A autoridade não exige dureza de rosto nem tom militar. Exige coerência. Se você disse que o tablet acaba às sete, acaba às sete, com calma, mesmo com choro. Se disse que vai contar até três e nada acontece no três, acabou de ensinar que a sua palavra não vale. Menos avisos, mais consequência; menos volume, mais firmeza. É a mesma decisão de "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"quem está começando a ser pai"},{"type":"text","text":" e precisa escolher que tipo de homem vai estar na frente dos filhos."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O método de 3 passos: parar, nomear, consequência"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Parar. "},{"type":"text","text":"Antes de abrir a boca, pare o que está fazendo, vá até a criança e fique na altura dos olhos dela. Gritar do outro cômodo é pedir para ser ignorado. Respire uma vez. Esse segundo é o que separa o pai do reator."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Nomear. "},{"type":"text","text":"Diga, em uma frase curta, o que está errado e o que você quer: “Brinquedo no chão machuca gente. Guarda agora, por favor.” Sem sermão, sem lembrar o que ele fez semana passada, sem rótulo (“você é bagunceiro”). A criança precisa saber o comportamento, não ouvir o julgamento."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Consequência. "},{"type":"text","text":"Se não obedecer, aplique a consequência combinada antes, sem raiva e sem negociar: o brinquedo fica guardado até amanhã, a tela acaba por hoje, saímos do parque agora. Consequência boa é imediata, proporcional e ligada ao erro. Castigo de um mês não ensina nada; só mostra que você perdeu a medida."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"O segredo é que a consequência seja conhecida de antemão. Combine as regras da casa com sua esposa, de preferência num momento tranquilo, e apresente para os filhos em conjunto. Pai e mãe falando a mesma língua valem por dez gritos. O método também se aplica a rotinas chatas, como escovar os dentes ou sentar à mesa, e funciona ainda melhor quando a casa tem ordem; um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"kit básico de ferramentas"},{"type":"text","text":" para consertar o que a criançada quebra evita muito estresse acumulado."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Frases que funcionam por idade"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Idade"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"O que funciona"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"O que evitar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1 a 3 anos"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Frases de três palavras, redirecionar, tirar do lugar: “Não. Aqui não. Vem.”"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Explicações longas, perguntas (“por que você fez isso?”), ameaças que não cumpre"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"4 a 7 anos"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Escolha entre duas opções aceitáveis; regra clara e consequência imediata"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Gritar de longe, sarcasmo, comparar com o irmão"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"8 a 12 anos"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Explicar o motivo uma vez, cobrar responsabilidade, consequência proporcional"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Humilhar na frente dos amigos, castigo longo demais, voltar atrás por pena"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Adolescência"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Conversa de homem para homem, acordos claros, ouvir antes de decidir"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Controle total, grito, ameaça de expulsar de casa"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Repare que, em todas as idades, a coluna do meio é curta e a da direita é cheia de grito. Limite é frase curta dita com a voz baixa. Quanto mais você fala, menos você é ouvido."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Quando você perde a paciência"}]},{"type":"paragraph","content":[{"type":"text","text":"Vai acontecer. Noite mal dormida, pressão no trabalho, conta atrasada, e o filho derruba o suco pela terceira vez. Você grita. O que define o pai não é nunca errar; é o que faz depois. Primeiro, saia de perto: vá ao banheiro, lave o rosto, respire fundo dez vezes. Depois, volte e peça perdão, olhando nos olhos: “Eu gritei com você e isso foi errado. Pai não devia gritar. Me desculpa.” Isso não enfraquece a sua autoridade; fortalece, porque mostra que a regra vale para você também."}]},{"type":"paragraph","content":[{"type":"text","text":"Em seguida, retome o limite com calma. Pedir perdão pelo grito não cancela a regra do suco. E leve isso para a confissão. O católico tem um remédio para a ira, e não é vergonha usá-lo; é sinal de homem que quer melhorar. Se você percebe que o cansaço é o gatilho principal, cuide do corpo: sono, alimentação e um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"treino curto de 20 minutos"},{"type":"text","text":" baixam a tensão mais do que qualquer técnica de respiração, e os "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"exames de rotina do homem"},{"type":"text","text":" descartam causas físicas para a irritação constante."}]},{"type":"paragraph","content":[{"type":"text","text":"Se a raiva aparece com frequência e você sente vontade de bater ou já bateu com força, pare de ler blogs e procure ajuda: um psicólogo, o seu padre, o médico de família. Isso não é fraqueza; é o ato mais forte que um pai pode fazer pelos filhos. E não se isole: um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante","class":null,"rel":null,"target":null}}],"text":"churrasco com amigos que também são pais"},{"type":"text","text":" vale mais do que muita teoria, e a seção "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/categoria/paternidade-por-fase","class":null,"rel":null,"target":null}}],"text":"Paternidade por fase"},{"type":"text","text":" traz o que esperar de cada idade."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semáforo do pai: limites e temperamento"}]},{"type":"callout","attrs":{"tone":"ok"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal verde: birras ocasionais, teste de limites nas fases de mudança, choro quando a regra é aplicada e, de vez em quando, um grito seu seguido de pedido de desculpa. A criança continua procurando você para brincar, contar coisas e pedir colo. O vínculo está saudável e o método está funcionando."}]}]},{"type":"callout","attrs":{"tone":"warn"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de atenção: o grito virou a forma normal de falar em casa, a criança só obedece quando você se altera, ela se encolhe ou se cala quando você entra no cômodo, os limites mudam conforme o seu humor, ou o casal discorda das regras na frente dos filhos. Hora de sentar com a esposa, rever as regras e combinar um plano com o método de três passos."}]}]},{"type":"callout","attrs":{"tone":"bad"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de alerta: explosões frequentes com vontade de bater, tapas ou puxões dados com raiva, criança com medo intenso do pai, pesadelos, agressividade ou retrocessos como voltar a fazer xixi na cama, ou você percebendo que não consegue se controlar. Não resolva sozinho: procure um psicólogo, converse com o seu padre e, se houver sinais físicos, leve a criança ao pediatra."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Limites e fé: disciplina é forma de amor"}]},{"type":"paragraph","content":[{"type":"text","text":"A Escritura diz que o Senhor corrige a quem ama, e que o pai que não disciplina o filho não o ama de verdade. Disciplina, na raiz da palavra, é a mesma de discípulo: alguém que aprende com um mestre. O pai que dá limite com calma está ensinando o filho a ser discípulo da ordem, da verdade e, no fim, de Deus. São José não aparece gritando em nenhuma página do Evangelho; aparece obedecendo, trabalhando e protegendo. Esse é o modelo de autoridade masculina."}]},{"type":"paragraph","content":[{"type":"text","text":"Reze pelos seus filhos, especialmente pelo que mais te tira do sério. E reze por você antes de corrigir: uma Ave-Maria mental entre o “parar” e o “nomear” do método faz mais efeito do que parece. A mesma serenidade vai te servir nas decisões de "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"dinheiro da família"},{"type":"text","text":", nas conversas difíceis com a esposa e até na hora de "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-segurar-um-recem-nascido-com-seguranca","class":null,"rel":null,"target":null}}],"text":"segurar o recém-nascido que chora"},{"type":"text","text":" de madrugada."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist do pai: limites sem gritar"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Combinar com a esposa as regras da casa e as consequências de cada uma"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Falar uma vez, na altura dos olhos, com frase curta e voz baixa"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Aplicar a consequência combinada sem raiva e sem negociar"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Pedir perdão quando gritar e retomar o limite com calma"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cuidar de sono, treino e confissão para controlar o próprio temperamento"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ficar atento aos sinais do semáforo acima"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Você não precisa gritar para ser obedecido; precisa ser coerente para ser respeitado. Cada vez que você para, respira e corrige com a voz baixa, seu filho aprende que a força de um homem está no controle, não no volume. Essa lição ele vai carregar para o casamento dele, para o trabalho dele e para os filhos dele. É o tipo de herança que não se compra."}]},{"type":"paragraph","content":[{"type":"text","text":"Continue lendo: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"Como ser um marido presente depois que o bebê chega"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"Rotina do pai nos primeiros 30 dias do bebê"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"Treino de 20 minutos em casa para pais sem tempo"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"Vai ser pai: o guia do primeiro trimestre para o homem"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}],"text":"Orçamento familiar para quem vai ser pai: passo a passo"},{"type":"text","text":" e "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"Kit básico de ferramentas para a casa: o que todo pai precisa ter"},{"type":"text","text":"."}]}]}$body$::jsonb,
  'https://images.unsplash.com/photo-1571650452577-755817f40c0a?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080',
  'Pai e filho sentados lado a lado em um píer, conversando',
  (select id from public.categories where slug = 'paternidade-por-fase'),
  coalesce((select id from auth.users where lower(email) = 'contato@vocacaodepai.com.br'), 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa'::uuid),
  'artigo',
  $faq$[{"question":"Dar limite sem gritar não é ser permissivo?","answer":"Não. Permissivo é quem não aplica a consequência. Pai de autoridade fala uma vez, com voz baixa, e cumpre o que disse. O grito é sinal de que a autoridade falhou, não de que ela existe."},{"question":"Com que idade a criança entende limite?","answer":"Desde o primeiro ano ela entende o “não” acompanhado de ação: tirar do lugar, redirecionar. O que muda com a idade é a quantidade de explicação. Quanto menor, mais curta a frase."},{"question":"E se minha esposa e eu discordamos das regras?","answer":"Resolvam longe dos filhos. Regra combinada entre pai e mãe vale por dez gritos; regra contestada na frente da criança não vale nada. Marquem uma conversa tranquila e definam as cinco regras mais importantes da casa."},{"question":"Gritei com meu filho. Estraguei tudo?","answer":"Não. O que define o pai é o que ele faz depois: sair de perto, respirar, voltar, pedir perdão olhando nos olhos e retomar o limite com calma. E levar isso para a confissão."},{"question":"Quando procurar ajuda profissional?","answer":"Quando a raiva é frequente, quando há vontade de bater ou já houve tapa com força, quando a criança demonstra medo intenso do pai ou tem retrocessos como voltar a fazer xixi na cama. Psicólogo, padre e pediatra são os primeiros a procurar."}]$faq$::jsonb,
  $quiz$[{"question":"Qual é a ordem do método de três passos?","options":["Gritar, explicar, castigar","Parar, nomear, consequência","Avisar três vezes, contar até três, ameaçar","Ignorar, esperar, perdoar"],"correct":1,"explanation":"Parar (ir até a criança e respirar), nomear (frase curta sobre o comportamento e o que você quer) e aplicar a consequência combinada, sem raiva e sem negociar."},{"question":"O que o grito ensina à criança?","options":["Que o pai está sempre certo","Que limite é ataque e que quem está nervoso pode descontar no menor","Que ela precisa obedecer na primeira vez","Nada, ela esquece rápido"],"correct":1,"explanation":"A criança aprende o que vê, não o que ouve. O grito ensina que o pai perde o controle e que limite vem com agressão."},{"question":"Com uma criança de 2 anos, o que funciona melhor?","options":["Explicar em detalhes por que aquilo é errado","Perguntar por que ela fez isso","Frase de três palavras e tirar do lugar","Castigo de uma semana"],"correct":2,"explanation":"Entre 1 e 3 anos a criança não acompanha explicação longa. Funciona a frase curta (“Não. Aqui não. Vem.”) seguida de ação."},{"question":"Você gritou e se arrependeu. Qual é o próximo passo correto?","options":["Fingir que não aconteceu para não perder autoridade","Dar um presente para compensar","Sair de perto, respirar, voltar e pedir perdão olhando nos olhos","Cancelar a regra que causou a briga"],"correct":2,"explanation":"Pedir perdão fortalece a autoridade porque mostra que a regra vale para o pai também. Depois, retoma-se o limite com calma; a regra continua."}]$quiz$::jsonb,
  'published',
  now() - interval '6 days',
  9,
  'Como dar limites sem gritar: autoridade com calma',
  'Método de três passos para corrigir sem gritar, frases que funcionam por idade, o que fazer quando você perde a paciência e quando buscar ajuda.'
)
