-- 5. Orçamento familiar para quem vai ser pai: passo a passo
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  'orcamento-familiar-para-quem-vai-ser-pai',
  'Orçamento familiar para quem vai ser pai: passo a passo',
  'Quanto pesa o primeiro ano de um filho, como montar o orçamento da casa em cinco categorias num fim de semana e onde cortar sem sofrer.',
  'Quanto custa o primeiro ano de um filho no Brasil, como montar o orçamento da casa em 5 categorias e onde cortar sem sofrer. Com tabela e checklist.',
  $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A notícia de que você vai ser pai vem junto com uma calculadora mental que não desliga: fralda, consulta, carrinho, berço, creche. E, no meio disso, a dúvida que todo homem provedor sente no estômago: vai dar? A resposta honesta é que depende menos de quanto você ganha e mais de como você organiza o que ganha. Filho não quebra família organizada; quebra família sem plano."}]},{"type":"paragraph","content":[{"type":"text","text":"Este guia mostra quanto pesa, em proporção da renda, o primeiro ano de um filho no Brasil, como montar o orçamento da casa em cinco categorias num único fim de semana, onde cortar sem sofrer e como construir a reserva de emergência antes do parto. Se você ainda está nas primeiras semanas, vale ler antes o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"guia do primeiro trimestre para o homem"},{"type":"text","text":"; o dinheiro é um dos capítulos dele."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Quanto custa, de verdade, o primeiro ano de um filho"}]},{"type":"paragraph","content":[{"type":"text","text":"Não existe número único, porque o custo depende da cidade, do plano de saúde, de a mãe continuar trabalhando e do que a família considera essencial. Mas existe uma ordem de grandeza útil: para uma família de renda média, o primeiro ano de um filho costuma consumir entre 15% e 25% da renda mensal da casa, sem contar a queda de renda se a mãe reduzir a jornada. Em famílias de renda mais baixa, a fatia é maior, porque fralda e fórmula custam o mesmo para todo mundo."}]},{"type":"paragraph","content":[{"type":"text","text":"Os blocos de gasto do primeiro ano, do maior para o menor, costumam ser estes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuidado diário: creche, babá ou a renda que a mãe deixa de receber para ficar em casa; é, de longe, o maior item"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fraldas, lenços, pomada e itens de higiene: gasto mensal constante, de seis a oito fraldas por dia no começo"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Saúde: plano de saúde do bebê, consultas de pediatra, vacinas fora do calendário público, remédios"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alimentação: fórmula, se houver, e depois a introdução alimentar; amamentação exclusiva reduz muito esse bloco"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enxoval e equipamentos: berço, carrinho, cadeirinha do carro, banheira; gasto concentrado antes do nascimento"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Roupas: compradas em quantidade pequena, porque o bebê cresce rápido; aqui entram muito bem as doações da família"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Repare que o maior custo não é o enxoval que todo mundo discute, é o cuidado diário. É nele que a conversa do casal precisa ser mais honesta, e é ele que decide se vale a pena, financeiramente, a mãe voltar ao trabalho em tempo integral ou não. A "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"divisão de tarefas dos primeiros 30 dias"},{"type":"text","text":" já é um bom ensaio dessa decisão."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"As 5 categorias do orçamento da casa"}]},{"type":"paragraph","content":[{"type":"text","text":"Esqueça planilhas com quarenta linhas. Orçamento que funciona para pai de primeira viagem tem cinco categorias, e toda despesa da casa cai em uma delas:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Moradia e contas fixas: "},{"type":"text","text":"aluguel ou prestação, condomínio, luz, água, gás, internet, celular, IPTU."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Alimentação e casa: "},{"type":"text","text":"supermercado, feira, padaria, produtos de limpeza, pequenas manutenções."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Filho: "},{"type":"text","text":"tudo o que listamos acima, do cuidado diário às fraldas, em uma linha só para você enxergar o tamanho."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Transporte e trabalho: "},{"type":"text","text":"combustível, transporte público, seguro e manutenção do carro, refeições fora, roupa de trabalho."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reserva, dívidas e dízimo: "},{"type":"text","text":"a parcela que vai para a reserva de emergência, o pagamento de dívidas e o que a família destina à Igreja e à caridade."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Lazer e gastos pessoais não ganharam categoria própria de propósito: eles entram como um valor fixo e pequeno dentro de “Alimentação e casa”, para o casal não brigar por eles. Cada um tem a sua cota, e acabou."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Passo a passo para montar o orçamento em um fim de semana"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sábado de manhã: somem toda a renda líquida da casa dos últimos três meses e tirem a média. É com a média que se planeja, não com o melhor mês."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sábado à tarde: peguem os extratos e classifiquem cada gasto dos últimos dois meses nas cinco categorias. Vai doer ver quanto foi para delivery; é para doer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Domingo de manhã: definam a fatia da renda para cada categoria usando a tabela abaixo como ponto de partida e ajustem à sua realidade."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Domingo à tarde: listem os cortes, abram uma conta separada para a reserva e combinem o dia do mês da conversa de revisão, que leva quinze minutos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Durante o mês: um aplicativo simples ou um caderno na cozinha. O melhor sistema é o que os dois conseguem manter."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Façam isso juntos. Orçamento feito só pelo marido e imposto à esposa não dura dois meses. O homem lidera a casa, e liderar é decidir em conjunto e sustentar a decisão, não mandar. Essa postura calma é a mesma que você vai precisar para "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}],"text":"dar limites aos filhos sem gritar"},{"type":"text","text":" e para ser "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"um marido presente depois que o bebê chega"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Onde cortar sem sofrer"}]},{"type":"paragraph","content":[{"type":"text","text":"Corte primeiro o que você não sente: assinaturas que ninguém usa, pacote de TV, plano de celular acima do necessário, tarifas bancárias que dá para zerar trocando de banco, seguro duplicado. Depois, ataque os gastos de conveniência: delivery, café fora, compras pequenas no mercado da esquina. Por último, renegocie o que é grande: aluguel, plano de saúde, parcelas do carro."}]},{"type":"paragraph","content":[{"type":"text","text":"Não corte o que sustenta a família por dentro: a missa, o almoço de domingo com os pais, o churrasco com os amigos. Um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante","class":null,"rel":null,"target":null}}],"text":"churrasco bem feito"},{"type":"text","text":" custa pouco quando você compra o corte certo na quantidade certa, e vale mais do que qualquer economia. E não corte a sua saúde: os "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":" são mais baratos do que qualquer tratamento tardio, e um "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"treino de 20 minutos em casa"},{"type":"text","text":" substitui a mensalidade da academia que você não frequenta."}]},{"type":"paragraph","content":[{"type":"text","text":"No enxoval, a regra é comprar o essencial, aceitar usado de gente de confiança e resistir à lista de loja. Berço, carrinho e cadeirinha de carro merecem atenção à segurança, não à marca. O resto o bebê não vai notar. Antes de comprar qualquer coisa para a casa, aliás, vale conferir se você já tem o "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"kit básico de ferramentas"},{"type":"text","text":" para montar o que chegar em caixa."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reserva de emergência antes do bebê nascer"}]},{"type":"paragraph","content":[{"type":"text","text":"Reserva de emergência é a quantia guardada em aplicação de resgate imediato e baixo risco, como um fundo conservador ou um título público de curto prazo, que cobre de três a seis meses dos gastos fixos da casa. Com filho, mire os seis meses. É ela que impede que uma demissão, uma cesárea não prevista pelo plano ou um carro quebrado virem dívida de cartão."}]},{"type":"paragraph","content":[{"type":"text","text":"Se você não tem nada guardado, comece pequeno e automático: uma transferência programada no dia do salário, antes de qualquer gasto. O valor importa menos do que a regularidade. E nunca, em hipótese alguma, troque a reserva por promessa de ganho rápido, aposta ou investimento que alguém da internet jura que não tem risco. Pai de família não aposta o leite do filho. Investimentos vêm depois da reserva, nunca antes, e sempre com estudo ou com um profissional de confiança. Aqui o site não dá recomendação de investimento: dá informação educativa."}]},{"type":"paragraph","content":[{"type":"text","text":"Dívida de cartão rotativo e cheque especial vêm antes de qualquer reserva, porque os juros deles são maiores do que qualquer rendimento. Se existe dívida assim, o plano do fim de semana ganha uma linha a mais: quitar ou renegociar. Os demais artigos da seção "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/categoria/dinheiro-do-pai","class":null,"rel":null,"target":null}}],"text":"Dinheiro do Pai"},{"type":"text","text":" aprofundam dívidas, reserva e investimentos."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semáforo do pai: dinheiro e gravidez"}]},{"type":"callout","attrs":{"tone":"ok"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal verde: as contas fecham no mês, o casal sabe quanto entra e quanto sai, a reserva está em construção, as compras do bebê seguem uma lista e o assunto dinheiro é conversado sem briga. Mantenha a revisão mensal e siga guardando."}]}]},{"type":"callout","attrs":{"tone":"warn"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de atenção: cartão no rotativo há mais de um mês, nenhuma reserva depois de dois meses de tentativa, compras do enxoval parceladas em muitas vezes, discussões frequentes por dinheiro ou gastos que um esconde do outro. Sente com a esposa esta semana, refaça as cinco categorias e corte antes que vire bola de neve."}]}]},{"type":"callout","attrs":{"tone":"bad"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de alerta: dívidas crescendo todo mês, cheque especial virando renda, empréstimo para pagar empréstimo, cobrança de agiota ou tentação de apostar para recuperar o prejuízo. Isso não se resolve sozinho nem com vídeo de internet: procure um contador ou planejador financeiro de confiança, os mutirões de renegociação dos bancos e, se a angústia pesar, o seu padre ou um psicólogo."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Como dividir a renda da casa com um filho"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Categoria"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Fatia da renda (ponto de partida)"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Exemplo do que entra"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Moradia e contas fixas"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"30% a 35%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Aluguel ou prestação, condomínio, luz, água, internet"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Alimentação e casa"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"20% a 25%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Mercado, feira, limpeza, cota de lazer de cada um"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Filho"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"15% a 25%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Creche ou babá, fraldas, pediatra, plano de saúde, fórmula"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Transporte e trabalho"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"10% a 15%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Combustível, ônibus, manutenção do carro, almoço fora"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Reserva, dívidas e dízimo"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"10% a 15%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Reserva de emergência, parcelas de dívida, contribuição à Igreja"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"As faixas somam mais de 100% de propósito: elas são limites, não metas. Família que mora de aluguel caro compensa no transporte; família com creche cara compensa na alimentação. O que não se negocia é a última linha: se a reserva fica em zero, o orçamento está errado. E, quando o bebê chegar e você estiver aprendendo a "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-segurar-um-recem-nascido-com-seguranca","class":null,"rel":null,"target":null}}],"text":"segurar o recém-nascido"},{"type":"text","text":", vai agradecer por não ter de pensar em boleto de madrugada."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist do pai: orçamento para quem vai ser pai"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Calcular a renda média líquida dos últimos três meses"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Classificar os gastos de dois meses nas cinco categorias"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cortar assinaturas, tarifas e conveniências antes de cortar o essencial"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Programar a transferência automática para a reserva no dia do salário"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Marcar a revisão mensal de quinze minutos com a esposa"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ficar atento aos sinais do semáforo acima"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Prover não é ganhar muito; é fazer o que se ganha servir à família com ordem e paz. O pai que senta com a esposa num fim de semana, encara os números e monta cinco categorias já está protegendo o filho antes de ele nascer. Faça isso agora, enquanto o bebê ainda cabe na barriga da mãe e a lista de gastos ainda cabe num guardanapo."}]},{"type":"paragraph","content":[{"type":"text","text":"Continue lendo: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem","class":null,"rel":null,"target":null}}],"text":"Vai ser pai: o guia do primeiro trimestre para o homem"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe","class":null,"rel":null,"target":null}}],"text":"Rotina do pai nos primeiros 30 dias do bebê"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}],"text":"Exames que todo homem deve fazer a partir dos 30 anos"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante","class":null,"rel":null,"target":null}}],"text":"Cortes de carne para churrasco: guia do pai iniciante"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}],"text":"Kit básico de ferramentas para a casa: o que todo pai precisa ter"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/como-ser-um-marido-presente-depois-que-o-bebe-chega","class":null,"rel":null,"target":null}}],"text":"Como ser um marido presente depois que o bebê chega"},{"type":"text","text":" e "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}],"text":"Treino de 20 minutos em casa para pais sem tempo"},{"type":"text","text":"."}]}]}$body$::jsonb,
  'https://images.unsplash.com/photo-1758522487140-f6d76156d7d3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080',
  'Homem sentado à mesa da cozinha revisando papéis e contas da casa',
  (select id from public.categories where slug = 'orcamento-familiar'),
  coalesce((select id from auth.users where lower(email) = 'contato@vocacaodepai.com.br'), 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa'::uuid),
  'artigo',
  $faq$[{"question":"Quanto custa o primeiro ano de um filho?","answer":"Não há número único. Para uma família de renda média, o primeiro ano costuma consumir entre 15% e 25% da renda mensal, sem contar a queda de renda se a mãe reduzir a jornada. O maior item é o cuidado diário (creche, babá ou a renda que a mãe deixa de receber), não o enxoval."},{"question":"Devo guardar reserva ou pagar dívida primeiro?","answer":"Dívida de cartão rotativo e cheque especial vêm antes, porque os juros são maiores do que qualquer rendimento. Quitada ou renegociada a dívida cara, a reserva vira prioridade, com transferência automática no dia do salário."},{"question":"Quanto de reserva de emergência preciso ter?","answer":"De três a seis meses dos gastos fixos da casa, em aplicação de resgate imediato e baixo risco. Com filho, mire os seis meses. Comece pequeno e regular; o valor importa menos do que a constância."},{"question":"Posso investir para o futuro do bebê?","answer":"Só depois de quitar dívida cara e montar a reserva. Investimento vem por último e sempre com estudo ou com um profissional de confiança. Este site não dá recomendação de investimento; dá informação educativa."},{"question":"Minha esposa e eu brigamos por dinheiro. O que fazer?","answer":"Façam o orçamento juntos, com cota de gasto pessoal fixa para cada um e uma revisão mensal de quinze minutos. Se as brigas continuam ou há gastos escondidos, procurem o padre ou um conselheiro de casais antes que vire ressentimento."}]$faq$::jsonb,
  $quiz$[{"question":"Qual é o maior gasto do primeiro ano de um filho, para a maioria das famílias?","options":["Enxoval e carrinho","Fraldas","Cuidado diário: creche, babá ou a renda que a mãe deixa de receber","Roupas"],"correct":2,"explanation":"O enxoval é o que mais se discute, mas o cuidado diário é o item que mais pesa, e é nele que o casal precisa ser mais honesto."},{"question":"Com que renda se planeja o orçamento?","options":["Com o melhor mês dos últimos seis","Com a média líquida dos últimos três meses","Com o salário bruto","Com a renda que você espera ter no ano que vem"],"correct":1,"explanation":"Planejar com a média líquida dos últimos três meses evita o erro clássico de orçar com o mês de bônus ou hora extra."},{"question":"O que fazer com uma dívida de cartão rotativo antes do bebê nascer?","options":["Ignorar e focar na reserva","Quitar ou renegociar antes de guardar qualquer reserva","Parcelar em mais vezes para caber no orçamento","Pagar o mínimo e esperar o bebê nascer"],"correct":1,"explanation":"Os juros do rotativo e do cheque especial superam qualquer rendimento. Dívida cara vem antes da reserva."},{"question":"Qual é o primeiro corte sugerido no artigo?","options":["A missa e o almoço de domingo","Assinaturas, tarifas e planos que ninguém usa","O plano de saúde","O check-up do pai"],"correct":1,"explanation":"Corte primeiro o que você não sente: assinaturas esquecidas, tarifas bancárias e pacotes acima do necessário. O que sustenta a família por dentro não se corta."}]$quiz$::jsonb,
  'published',
  now() - interval '5 days',
  9,
  'Orçamento familiar para quem vai ser pai: passo a passo',
  'Quanto pesa o primeiro ano de um filho, as cinco categorias do orçamento da casa, onde cortar sem sofrer e como montar a reserva antes do parto.'
)
