  cover_image_url = excluded.cover_image_url, cover_image_alt = excluded.cover_image_alt, category_id = excluded.category_id,
  author_id = excluded.author_id, kind = excluded.kind, faq = excluded.faq, quiz = excluded.quiz,
  reading_time = excluded.reading_time, seo_title = excluded.seo_title, seo_description = excluded.seo_description,
  status = 'published', publish_at = coalesce(public.posts.publish_at, excluded.publish_at), updated_at = now();
